def rec(remaining, chosen):
  if not remaining:
    solutions.append(chosen[:]); return
  x=min(remaining)
  for name,col,p in pieces:
    if x in p and p<=remaining:
      rec(remaining-p,chosen+[(name,col,sorted(p))])
rec(cells,[])
